SourceCode.Declaration:
/// <summary>
/// Deletes the old records of the infolog call stack log. The log has no other limit, so schedule this in batch.
/// </summary>
public class DEVCSXppCallStackCleanup extends RunBaseBatch implements BatchRetryable
{
    Days         keepDays;

    DialogField  dlgKeepDays;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        keepDays
    #endmacro

}

Method.Source:
public Object dialog()
{
    DialogRunbase       dialog = super();

    dlgKeepDays = dialog.addFieldValue(extendedTypeStr(Days), keepDays, "Days to keep", "Call stack records older than this number of days are deleted. 0 deletes all records");

    return dialog;
}

public boolean getFromDialog()
{
    keepDays = dlgKeepDays.value();

    return super();
}

public Days parmKeepDays(Days _keepDays = keepDays)
{
    keepDays = _keepDays;
    return keepDays;
}

public boolean unpack(container _packedClass)
{
    Version    version = RunBase::getVersion(_packedClass);
    switch (version)
    {
        case #CurrentVersion:
            [version,#CurrentList] = _packedClass;
            break;
        default:
            return false;
    }
    return true;
}

public void run()
{
    DEVCSXppCallStackTable  callStackTable;
    utcdatetime             deleteBefore = DateTimeUtil::addDays(DateTimeUtil::utcNow(), -1 * keepDays);
    utcdatetime             chunkBefore;
    int64                   chunkRecords;
    int64                   deletedRecords;

    // One transaction per hour of the log, the oldest first: a large log is not deleted in one large transaction
    while (true)
    {
        select firstonly RecId, CreatedDateTime from callStackTable
            order by CreatedDateTime
            where callStackTable.CreatedDateTime < deleteBefore;

        if (! callStackTable.RecId)
        {
            break;
        }

        chunkBefore = DateTimeUtil::addHours(callStackTable.CreatedDateTime, 1);
        if (chunkBefore > deleteBefore)
        {
            chunkBefore = deleteBefore;
        }

        ttsbegin;
        delete_from callStackTable
            where callStackTable.CreatedDateTime < chunkBefore;
        chunkRecords = callStackTable.RowCount();
        ttscommit;

        if (! chunkRecords)
        {
            break;
        }
        deletedRecords += chunkRecords;
    }

    info(strFmt("%1 call stack records created before %2 were deleted", deletedRecords,
        DateTimeUtil::applyTimeZoneOffset(deleteBefore, DateTimeUtil::getUserPreferredTimeZone())));
}

public static DEVCSXppCallStackCleanup construct()
{
    return new DEVCSXppCallStackCleanup();
}

static ClassDescription description()
{
    return "Clean up the infolog call stack log";
}

public static void main(Args _args)
{
    DEVCSXppCallStackCleanup    runObject = DEVCSXppCallStackCleanup::construct();

    if (runObject.prompt())
    {
        runObject.runOperation();
    }
}
